+        buffer.allocate_buf(30).unwrap();
+        buffer.free_buf(|_, _| true, None);
+
+        // 48 bytes do not fit after the freed tail, so allocation wraps.
+        let (address, id) = buffer.allocate_buf(40).unwrap();
