+        let (address, _) = buffer.allocate_buf(20).unwrap();
+        assert_eq!(address, 72);
+        // Next chunk wraps to offset 100: 100 + 28 - 32 = 96 fits.
+        let (address, _) = buffer.allocate_buf(20).unwrap();
+        assert_eq!(address, 100);
